"use client";

/**
 * Dev-only design surface for the OG cards — /og-preview
 *
 * The cards are generated by satori (next/og), which renders server-side to a
 * PNG. That makes design iteration slow and blind: no devtools, no hot reload
 * you can actually see, and the usual sanity check (curl the route) returns a
 * valid PNG whether or not the card looks right.
 *
 * This page renders the REAL image routes in <img> tags at true 1200x630, so a
 * save-and-refresh shows exactly what a crawler would receive. It is not a
 * reimplementation of the cards — reimplementing them in DOM would drift from
 * satori's own layout engine and defeat the purpose. What you see here is the
 * actual PNG bytes.
 *
 * Excluded from search/crawlers via robots below; harmless if it ships, but
 * it's a tool, not a product surface.
 */

import { useCallback, useEffect, useState } from "react";
import { MARKETS, MARKET_ORDER } from "@/lib/markets";
import type { MarketSymbol } from "@/types";

/**
 * Cache-buster: image routes are cached hard, so a refresh alone can lie.
 *
 * Starts at 0 rather than `Date.now()` — seeding from the clock makes the
 * server and client render different `src` URLs and React reports a hydration
 * mismatch. The first paint doesn't need busting (it's a fresh request); only
 * subsequent reloads do.
 */
function useReloadKey() {
  const [key, setKey] = useState(0);
  const reload = useCallback(() => setKey(Date.now()), []);
  return [key, reload] as const;
}

type Card = { id: string; title: string; note: string; src: string };

const FRAME_W = 1200;
const FRAME_H = 630;

export default function OgPreview() {
  const [key, reload] = useReloadKey();
  // Fit the 1200px-wide card into whatever width the window gives us.
  const [scale, setScale] = useState(1);
  const [zoom, setZoom] = useState<"fit" | "full">("fit");
  const [market, setMarket] = useState<MarketSymbol>("BTC");

  useEffect(() => {
    const fit = () => {
      // 64px of page padding either side.
      const avail = Math.min(window.innerWidth - 64, 1280);
      setScale(Math.min(1, avail / FRAME_W));
    };
    fit();
    window.addEventListener("resize", fit);
    return () => window.removeEventListener("resize", fit);
  }, []);

  // `r` re-fetches both cards without a full page reload.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "r" && !e.metaKey && !e.ctrlKey) reload();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [reload]);

  const shown = zoom === "fit" ? scale : 1;

  const cards: Card[] = [
    {
      id: "root",
      title: "Root card",
      note: "app/opengraph-image.tsx — shown for / and any page without its own card",
      src: `/opengraph-image?v=${key}`,
    },
    {
      id: "market",
      title: `Market card — ${market}`,
      note: `app/trade/[market]/opengraph-image.tsx — shown for /trade/${market}`,
      src: `/trade/${market}/opengraph-image?v=${key}`,
    },
  ];

  return (
    // `tool-root` is the hook that re-enables document scrolling — the app's
    // body is `overflow: hidden` because the chart owns the viewport on real
    // routes, which would otherwise clip this page's lower card. See globals.css.
    <main
      className="tool-root"
      style={{
        minHeight: "100vh",
        background: "#0b0e11",
        color: "#e8eaed",
        padding: 32,
        fontFamily: "system-ui, sans-serif",
      }}
    >
      <header style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 22, fontWeight: 700, margin: 0 }}>OG image preview</h1>
        <p style={{ color: "#8b90a0", fontSize: 14, margin: "8px 0 0" }}>
          Live output of the real image routes at {FRAME_W}×{FRAME_H}. Edit{" "}
          <code style={code}>app/opengraph-image.tsx</code> or{" "}
          <code style={code}>app/trade/[market]/opengraph-image.tsx</code>, save, then
          hit Reload (or press <kbd style={code}>r</kbd>).
        </p>
        <p style={{ color: "#6b7080", fontSize: 13, margin: "8px 0 0" }}>
          These are the actual PNG bytes a crawler receives — not a DOM mock-up, so
          satori quirks show up here rather than in production.
        </p>
      </header>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 28 }}>
        <button onClick={reload} style={btn(true)}>
          Reload cards
        </button>
        {/* When the window is already wide enough to show the card 1:1, `fit`
            and `full` are the same size and this toggle would be a no-op that
            still claimed it could zoom. Disable it and say why instead. */}
        <button
          onClick={() => setZoom(zoom === "fit" ? "full" : "fit")}
          disabled={scale === 1}
          title={
            scale === 1
              ? "Window is already wide enough to show the card at 1:1"
              : undefined
          }
          style={{
            ...btn(zoom === "full"),
            ...(scale === 1 ? { opacity: 0.45, cursor: "default" } : null),
          }}
        >
          {scale === 1
            ? "Actual size (100%)"
            : zoom === "fit"
              ? `Zoom to actual size (now ${Math.round(scale * 100)}%)`
              : `Fit to window (${Math.round(scale * 100)}%)`}
        </button>

        <span style={{ width: 1, background: "#2a2e3a", margin: "0 4px" }} />

        {MARKET_ORDER.map((sym) => (
          <button
            key={sym}
            onClick={() => setMarket(sym)}
            style={btn(sym === market)}
            title={MARKETS[sym].label}
          >
            {sym}
          </button>
        ))}
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 40 }}>
        {cards.map((c) => (
          <section key={c.id}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 12, marginBottom: 10 }}>
              <h2 style={{ fontSize: 15, fontWeight: 600, margin: 0 }}>{c.title}</h2>
              <a href={c.src} target="_blank" rel="noreferrer" style={link}>
                open PNG ↗
              </a>
            </div>
            <p style={{ color: "#6b7080", fontSize: 12, margin: "0 0 12px" }}>{c.note}</p>

            {/* Fixed-size box so the scaled image doesn't collapse the layout. */}
            <div
              style={{
                width: FRAME_W * shown,
                height: FRAME_H * shown,
                // At actual size on a narrow window the card is wider than the
                // page; cap the box and let it scroll sideways rather than
                // pushing the whole document into a horizontal scroll.
                maxWidth: "100%",
                overflow: zoom === "full" ? "auto" : "hidden",
                borderRadius: 12,
                border: "1px solid #2a2e3a",
                // Checkerboard: any transparency in the card reads as a bug,
                // since most platforms composite previews onto white.
                backgroundImage:
                  "linear-gradient(45deg,#15181e 25%,transparent 25%,transparent 75%,#15181e 75%)," +
                  "linear-gradient(45deg,#15181e 25%,transparent 25%,transparent 75%,#15181e 75%)",
                backgroundSize: "20px 20px",
                backgroundPosition: "0 0, 10px 10px",
                backgroundColor: "#0e1116",
              }}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={c.src}
                alt={c.title}
                width={FRAME_W}
                height={FRAME_H}
                style={{
                  width: FRAME_W,
                  height: FRAME_H,
                  transform: `scale(${shown})`,
                  transformOrigin: "top left",
                  display: "block",
                }}
              />
            </div>
          </section>
        ))}
      </div>

      <footer style={{ marginTop: 44, color: "#6b7080", fontSize: 12, lineHeight: 1.7 }}>
        <strong style={{ color: "#8b90a0" }}>Notes</strong>
        <br />
        satori supports only a subset of CSS: flexbox only, no absolute positioning,
        every text node needs an explicit <code style={code}>display</code>, and a
        broken style yields a blank card on a <em>200 image/png</em> response — so a
        card that renders empty here is a layout bug, not a network one.
        <br />
        What a crawler actually fetches is the absolute URL in the page&apos;s{" "}
        <code style={code}>og:image</code> tag, which comes from{" "}
        <code style={code}>metadataBase</code> — this page bypasses that, so it proves
        the design, not the deployment.
      </footer>
    </main>
  );
}

const code: React.CSSProperties = {
  background: "#15181e",
  border: "1px solid #2a2e3a",
  borderRadius: 4,
  padding: "1px 5px",
  fontSize: 12,
  fontFamily: "ui-monospace, monospace",
};

const link: React.CSSProperties = {
  color: "#72E912",
  fontSize: 12,
  textDecoration: "none",
};

function btn(active: boolean): React.CSSProperties {
  return {
    background: active ? "rgba(114,233,18,0.12)" : "#15181e",
    border: `1px solid ${active ? "rgba(114,233,18,0.45)" : "#2a2e3a"}`,
    color: active ? "#72E912" : "#e8eaed",
    borderRadius: 8,
    padding: "8px 14px",
    fontSize: 13,
    fontWeight: 600,
    cursor: "pointer",
  };
}
